    "value":  "use smallest::*;\r\nuse std::collections::HashMap;\r\n\r\n#[test]\r\nfn test_positive() {\r\n    let f = HashMap::from([\r\n        (\"Cat\", 12),\r\n        (\"Dog\", 333),\r\n        (\"Elephant\", 334),\r\n        (\"Gorilla\", 14),\r\n        (\"Dolphin\", 2),\r\n    ]);\r\n\r\n    assert_eq!(2, smallest(f));\r\n}\r\n\r\n#[test]\r\nfn test_negative() {\r\n    let f = HashMap::from([\r\n        (\"Daniel\", 41758712),\r\n        (\"Ashley\", 54551444),\r\n        (\"Katie\", 575556334),\r\n        (\"Roberti\", 574148),\r\n        (\"Robert\", -4),\r\n    ]);\r\n\r\n    assert_eq!(-4, smallest(f));\r\n}\r\n\r\n#[test]\r\nfn test_zero() {\r\n    let f = HashMap::from([\r\n        (\"Mars\", 1223),\r\n        (\"Jupiter\", 33343),\r\n        (\"Saturn\", 12443334),\r\n        (\"Neptune\", 14),\r\n        (\"Venus\", 0),\r\n    ]);\r\n\r\n    assert_eq!(0, smallest(f));\r\n}\r\n\r\n#[test]\r\nfn empty() {\r\n    let f = HashMap::new();\r\n\r\n    assert_eq!(i32::MAX, smallest(f));\r\n}\r\n",
