    "value":  "#[cfg(test)]\r\nmod tests {\r\n    use insertion_sort::*;\r\n\r\n    #[test]\r\n    fn it_works() {\r\n        let mut target = [5, 3, 7, 2, 1, 6, 8, 4];\r\n        let len = target.len();\r\n        insertion_sort(\u0026mut target, len - 1);\r\n        assert_eq!(\u0026[1, 2, 3, 4, 5, 6, 7, 8], \u0026target);\r\n    }\r\n\r\n    #[test]\r\n    fn test_first_step() {\r\n        let mut target = [5, 3, 7, 2, 1, 6, 8, 4];\r\n        insertion_sort(\u0026mut target, 1);\r\n        assert_eq!(\u0026[3, 5, 7, 2, 1, 6, 8, 4], \u0026target);\r\n    }\r\n\r\n    #[test]\r\n    fn test_second_step() {\r\n        let mut target = [5, 3, 7, 2, 1, 6, 8, 4];\r\n        insertion_sort(\u0026mut target, 2);\r\n        assert_eq!(\u0026[3, 5, 7, 2, 1, 6, 8, 4], \u0026target);\r\n    }\r\n}\r\n",
